197	        int time = waitForGlobalLock();
198	        debug("TXValidateNested: time = " + time);
199	        for (Map.Entry<MutableFValue,FValue> entry : reads.entrySet()) {
200	            MutableFValue key = entry.getKey();
201	            FValue val = entry.getValue();
202	            FValue ancestrialWrite = parent.AncestrialWrite(key);
203	            debug("TXValidateNested: key = " + key + " val = " + val + " ancestrialWrite = " + ancestrialWrite);
204	            if (ancestrialWrite == null) {
205	                if (key.getValue() != val)
206	                    TXAbort();
207	            } else {
208	                if (ancestrialWrite != val)
209	                    TXAbort();
210	            }
