231	    public void TXCommit() {
232	        debug("TXCommit: reads = " + reads + " writers = " + writes);
233	        if (writes.isEmpty())
234	            return;
235	
236	        int time = snapshot.get();
237	            
238	        while (! getGlobalLock(time)) {
239	            time = TXValidate();
240	            debug("TXCommitFail: time " + time);
241	            snapshot.set(time);
242	        }
243	            
244	        if (this == topLevelTransaction) {
245	       
246	            for (Map.Entry<MutableFValue,FValue> entry : writes.entrySet()) {
247	                MutableFValue key = entry.getKey();
248	                FValue val = entry.getValue();
249	                debug("TXCommitting:  time = " + time + " key = " + key + " val = " + val);
250	                key.setValue(val);
251	            }
252	       
253	        } else {
254	
255	            for (Map.Entry<MutableFValue,FValue> entry : reads.entrySet()) {
256	                MutableFValue key = entry.getKey();
257	                FValue val = entry.getValue();
258	                FValue ancestrialValue = parent.AncestrialWrite(key);
259	
260	                // This is subtle.  If the child read a value written by a grandparent, then it has to go in the 
261	                // the parent's read set, because otherwise a cousin transaction could update the value written
262	                // in the grandparent and the parent transaction wouldn't know to abort.
263	                if (parent.writes.get(key) == null) {
264	                    parent.reads.put(key, val);
265	                    debug("TXCommitting: read to parent without ancestrial write: snapshot = " + snapshot + " time = " + time + " key = " + key + " val = " + val);
266	                }
267	            }
268	
269	
270	            for (Map.Entry<MutableFValue,FValue> entry : writes.entrySet()) {
271	                MutableFValue key = entry.getKey();
272	                FValue val = entry.getValue();
273	                parent.writes.put(key, val);
274	                debug("TXCommitting: write to parent: snapshot = " + snapshot.get() + " time = " + time + " key = " + key + " val = " + val);
275	            }
276	        }
277	
278	        if (! releaseGlobalLock(time+1))
279	            throw new RuntimeException("Who messed with a committing transaction?");
280	    }
